import React from "react";
import { Link } from "react-router-dom";

import IndexNavbar from "components/Navbars/IndexNavbar.js";
import Footer from "components/Footers/Footer.js";
import HeroImage from "assets/img/bg1.png";
import BannerImage from "assets/img/banniere.png";
import NewsStack from "components/newsStack";

import News1 from "assets/img/mbaye.png";
import News2 from "assets/img/newdeal.jpg";
import News3 from "assets/img/sim.jpg";

import IconResto from "assets/img/menu.png";
import IconRess from "assets/img/ressources.png";
import IconRH from "assets/img/rh.png";
import IconCom from "assets/img/commercial.png";
import IconMoy from "assets/img/moyens.png";
import IconForm from "assets/img/formation.png";

import PrettyCalendar from "components/calendar";

export default function Index() {
  const resources = [
    { label: "Omni365", href: "#" },
    { label: "Vision Accel", href: "#" },
    { label: "Karangue", href: "#" },
  ];
  const life = [
    { label: "Qui fait quoi ?", href: "#" },
    { label: "Initiative QVT", href: "#" },
    { label: "Temps forts RH", href: "#" },
    { label: "Voir plus", href: "#" },
  ];
  const ICON_ROW_OFFSET_PX = -1150;
  return (
    <>
      <IndexNavbar fixed />

      {/* HERO */}
      <section
        className="relative mt-16 md:mt-20 h-screen max-h-860-px flex items-center"
        style={{
          backgroundImage: `linear-gradient(rgba(107, 20, 15, 0.65), rgba(107, 20, 15, 0.25)), url(${HeroImage})`,
          backgroundSize: "cover",
          backgroundPosition: "center 30%",
          backgroundRepeat: "no-repeat",
        }}
      >
        <div className="container mx-auto relative z-10 flex flex-wrap items-center">
          <div className="w-full lg:w-6/12 px-4">
            <h1 className="font-bold text-5xl md:text-7xl text-white leading-tight">
              Dalal ak jàamm,
            </h1>
            <p className="mt-6 text-2xl md:text-3xl font-light text-white max-w-xl">
              Mame Samba NDIAYE !
            </p>
          </div>
        </div>
      </section>

      <section className="relative bg-white py-16">
        <div className="container mx-auto px-4">
          <div className="flex flex-row items-start space-x-8">
            <div className="w-1/2 min-w-0">
              <h3 className="text-[#1c2b68] font-semibold text-xl mb-3">
                Un jour spécial pour ?
              </h3>
              <PrettyCalendar
                initialYear={2023}
                initialMonth={2}
                selectedDay={20}
                events={[
                  { date: "2023-02-20", label: "Anniversaire de Ousmane DIA" },
                  { date: "2023-02-16", label: "Réunion Produits" },
                ]}
              />
            </div>

            <div className="w-1/2 min-w-0">
              <h3 className="text-[#1c2b68] font-semibold text-xl mb-3">
                Actualités
              </h3>
              <NewsStack
                items={[

                  {
                    img: News2,

                    href: "#",
                  },
                  {
                    img: News3,

                    href: "#",
                  }, {
                    img: News1,

                    href: "#",
                  },
                ]}
              />
            </div>
          </div>
        </div>
      </section>



      <section
        className="relative z-30 w-full"
        style={{ marginTop: ICON_ROW_OFFSET_PX }}
      >
        <div className="w-full">
          <div className="flex flex-nowrap items-start justify-center gap-10 px-6 lg:px-12 overflow-x-auto no-scrollbar">
            {[
              { img: IconResto, label: "Restauration" },
              { img: IconRess, label: "Ressources" },
              { img: IconRH, label: "RH" },
              { img: IconCom, label: "Commercial" },
              { img: IconMoy, label: "Moyens généraux" },
              { img: IconForm, label: "Formation" },
            ].map((item, idx) => (
              <div
                key={idx}
                className="flex flex-col items-center shrink-0"
              >
                {/* Carte blanche arrondie + ombre douce comme sur ta maquette */}
                <div className="w-40 h-40 bg-white rounded-[20px] shadow-[0_10px_24px_rgba(0,0,0,0.12)] flex items-center justify-center">
                  <img src={item.img} alt={item.label} className="w-16 h-16 object-contain" />
                </div>
                {/* Libellé dessous */}
                <div className="mt-4 text-center">
                  <span className="text-[22px] leading-tight font-semibold text-[#0b132b]">
                    {item.label}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>
      <div className=" h-[200px]"></div> {/* 128px de vide, ajuste avec h-20, h-40, h-[200px] etc. */}

      <section className="relative w-full">
        <img
          src={BannerImage}
          alt="Bannière"
          className="w-full h-[500px] object-cover"
        />
      </section>
      {/* FEATURES (optionnel) */}
      <section id="features" className="py-24 bg-blueGray-50">
        <div className="container mx-auto px-4 text-center max-w-3xl">
          <h2 className="text-3xl md:text-4xl font-semibold text-blueGray-800">
            Ce que vous obtenez
          </h2>
        </div>
      </section>

      {/* <Footer /> */}
    </>
  );
}
